import nodemailer from "nodemailer";

/**
 * Sends a store owner the link that lets them authorize leStores to connect
 * to their own Shopify store.
 *
 * The link contains a signed, single-use token and is generated by
 * src/lib/shopifyOAuth.js — it is never logged.
 *
 * @param {object} args
 * @param {string} args.to            recipient email address
 * @param {string} args.recipientName name to greet, may be empty
 * @param {string} args.shopDomain    e.g. "their-store.myshopify.com"
 * @param {string} args.authorizeUrl  the Shopify authorization link
 */
export async function sendShopifyConnectRequestEmail({
  to,
  recipientName = "",
  shopDomain,
  authorizeUrl,
}) {
  const logoURL = `${process.env.NEXT_PUBLIC_FRONTEND_LIVE_URL}/images/fash.png`;

  const transporter = nodemailer.createTransport({
    host: process.env.SMTP_HOST,
    port: process.env.SMTP_PORT,
    secure: process.env.SMTP_SECURE === "true",
    auth: {
      user: process.env.EMAIL_USER,
      pass: process.env.EMAIL_PASS,
    },
    tls: {
      rejectUnauthorized: false,
    },
  });

  const greeting = recipientName ? `Hello ${recipientName},` : "Hello,";

  await transporter.sendMail({
    from: process.env.EMAIL_USER,
    to,
    subject: "Connect your Shopify store to leStores",
    html: `
      <div style="font-family: Arial, sans-serif; max-width: 600px; margin: auto; padding: 20px; border: 1px solid #ddd; border-radius: 8px; background-color: #f9f9f9;">
        <div style="text-align: center; margin-bottom: 20px;">
          <img src="${logoURL}" alt="leStores" style="max-width: 150px; height: auto;">
        </div>
        <h2 style="color: #333; text-align: center;">Connect your Shopify store</h2>
        <p style="font-size: 16px; color: #555;">
          ${greeting}<br><br>
          We'd like to connect your Shopify store <strong>${shopDomain}</strong> to your leStores account.
          Once connected, the products you create in leStores can be published to your own Shopify store
          automatically.
        </p>
        <p style="font-size: 16px; color: #555;">
          Click the button below to review the permissions and approve the connection. You'll be taken to
          Shopify's own authorization page.
        </p>
        <div style="text-align: center; margin: 24px 0;">
          <a href="${authorizeUrl}"
            style="background-color: #007bff; color: white; padding: 12px 20px; text-decoration: none; font-size: 16px; border-radius: 5px; display: inline-block;">
            Approve Shopify connection
          </a>
        </div>
        <div style="background-color: #eef6ff; border: 1px solid #cfe3ff; border-radius: 6px; padding: 12px 16px; margin: 20px 0;">
          <p style="font-size: 14px; color: #33507a; margin: 0;">
            <strong>Your login details are never shared.</strong> You approve the connection directly with
            Shopify, and leStores never sees your Shopify password. You can revoke access at any time from
            your Shopify admin under <em>Settings &rarr; Apps and sales channels</em>.
          </p>
        </div>
        <p style="font-size: 14px; color: #777;">
          This link is valid for <strong>7 days</strong> and can only be used once. If it expires, just ask
          us for a new one.
        </p>
        <p style="font-size: 14px; color: #777;">
          If you weren't expecting this email, you can safely ignore it — nothing will be connected unless
          you approve it.
        </p>
      </div>
    `,
  });
}
